import {lessons,judge} from './lessons.js';
import {generateLesson} from './missions.js';
import {validate} from './motion.js';
export function installLearning(trainer){
 const $=id=>document.getElementById(id);let lesson=lessons[0],userShot=null,example=false,result=null,serial=0,history=[];
 try{const saved=JSON.parse(localStorage.getItem('cct-course-v2')||'{}');history=Array.isArray(saved.history)?saved.history.filter(h=>h?.shot&&h?.lesson).slice(-100):[];serial=Number.isInteger(saved.serial)?saved.serial:0;}catch{}
 const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 for(const l of lessons){const o=document.createElement('option');o.value=l.id;o.textContent=l.title;$('lesson').append(o);}
 const generated=document.createElement('option');generated.value='generated';generated.textContent='새 문제 · 계속 생성';$('lesson').append(generated);
 const next=document.createElement('button');next.id='nextLesson';next.textContent='다음 새 문제';$('retry').after(next);
 function persist(){try{localStorage.setItem('cct-course-v2',JSON.stringify({serial,history}));}catch{$('viewing').textContent='학습 기록 저장 공간이 부족합니다. JSON으로 백업하세요.';}}
 function active(){return example?userShot:trainer.snapshot().state;}
 function switchView(isExample){if(isExample&&!example)userShot=trainer.snapshot().state;if(!isExample&&example)trainer.set(userShot);if(isExample)trainer.set(lesson.example);example=isExample;$('myShot').classList.toggle('active',!example);$('exampleShot').classList.toggle('active',example);$('viewing').textContent=example?'예시 시점 · 수정한 내 설계는 보존되어 있습니다.':'내 설계 편집 중';}
 function showLesson(l,shot=l.initial){lesson=l;example=false;userShot=null;result=null;trainer.set(shot);$('lessonTitle').textContent=l.title;$('lessonGoal').textContent=l.goal;$('lessonTip').textContent=l.tip;$('lesson').value=lessons.some(x=>x.id===l.id)?l.id:'generated';$('feedback').replaceChildren();$('comparison').hidden=true;$('myShot').classList.add('active');$('exampleShot').classList.remove('active');$('viewing').textContent='내 설계 편집 중';}
 function evaluate(s){const measured=trainer.analyze(s);return judge(lesson.type||lesson.id,measured.samples,measured.meta,lesson.criteria||{});}
 function comparison(){const s=active(),reference=lesson.example;const r=evaluate(s),er=evaluate(reference);$('comparison').innerHTML=`<p>내 설계 ${r.score}% / 예시 ${er.score}% · 같은 촬영장의 실제 3D 렌더링입니다.</p><div class="comparison-grid">${[[s,'내 설계'],[reference,'예시']].map(([shot,label])=>`<div>${[0,1].map((q,i)=>`<figure><img alt="${label} ${i?'종료':'시작'} 구도" src="${trainer.capture(shot,q)}"><figcaption>${label} · ${i?'종료':'시작'} 구도</figcaption></figure>`).join('')}</div>`).join('')}</div><p>${escape(lesson.why)}</p><p class="note">예시는 가능한 접근법 하나입니다. 중앙 구도·다른 경로도 문제 목적을 충족하면 인정합니다.</p>`;$('comparison').hidden=false;}
 function historyUI(){$('progress').textContent=`학습 기록 · ${history.length}회 / 유형 ${new Set(history.map(h=>h.lesson.type||h.lesson.id)).size}개`;$('history').replaceChildren();for(const h of [...history].reverse().slice(0,20)){const button=document.createElement('button');button.textContent=`${h.lesson.title} · ${h.score}% · ${new Date(h.at).toLocaleDateString('ko-KR')}`;button.onclick=()=>showLesson(h.lesson,validate(h.shot));$('history').append(button);}if(!history.length)$('history').textContent='평가한 촬영이 여기에 저장됩니다.';}
 $('lesson').onchange=()=>{if($('lesson').value==='generated'){serial++;showLesson(generateLesson(serial));persist();}else showLesson(lessons.find(l=>l.id===$('lesson').value));};next.onclick=()=>{serial++;showLesson(generateLesson(serial));persist();};$('retry').onclick=()=>showLesson(lesson);
 $('myShot').onclick=()=>switchView(false);$('exampleShot').onclick=()=>{switchView(true);document.getElementById('restart').click();};$('compare').onclick=comparison;
 $('evaluate').onclick=()=>{if(example)switchView(false);const s=trainer.snapshot().state;trainer.seek(0);result=evaluate(s);$('feedback').innerHTML=`<h2>측정 기준 달성률 ${result.score}%</h2><div class="checks">${result.checks.map(c=>`<div class="check-card ${c.ok?'good':'improve'}"><strong>${c.ok?'✓ 잘한 점':'△ 개선할 점'} · ${escape(c.name)}</strong><p>${escape(c.evidence)}</p>${c.ok?'':`<p>${escape(c.advice)}</p>`}</div>`).join('')}</div><p>추천 접근: ${escape(lesson.why)}</p><button id="inspectWorst">가림·이탈 점검 시점 ${(result.worst.t*s.duration).toFixed(1)}초 보기</button>`;$('inspectWorst').onclick=()=>trainer.seek(result.worst.t);history.push({lesson:structuredClone(lesson),shot:s,score:result.score,at:new Date().toISOString()});history=history.slice(-100);persist();historyUI();comparison();};
 $('export').onclick=()=>{const payload={version:2,shot:active(),lesson,serial,history};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='camera-learning-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>3000000)throw Error('백업 파일이 너무 큽니다.');const raw=JSON.parse(await file.text());if(raw.version===2){const s=validate(raw.shot);if(!raw.lesson||typeof raw.lesson.goal!=='string'||!raw.lesson.example||!raw.lesson.initial)throw Error('문제 정보가 잘못되었습니다.');validate(raw.lesson.example);validate(raw.lesson.initial);const incoming=Array.isArray(raw.history)?raw.history.slice(-100):[];for(const h of incoming){validate(h.shot);if(!h.lesson||typeof h.lesson.title!=='string')throw Error('학습 기록 형식이 잘못되었습니다.');}history=incoming;serial=Number.isInteger(raw.serial)?raw.serial:0;showLesson(raw.lesson,s);persist();historyUI();}else trainer.set(validate(raw));$('viewing').textContent='백업을 복원했습니다.';}catch(e){$('viewing').textContent=e.message;}e.target.value='';};
 $('save').onclick=()=>{try{const shot=active();localStorage.setItem('cct-shot-v1',JSON.stringify(shot));localStorage.setItem('cct-saved-session-v2',JSON.stringify({lesson,shot}));$('viewing').textContent='현재 문제와 내 촬영 설계를 저장했습니다.';}catch{$('viewing').textContent='저장하지 못했습니다. JSON 백업을 사용하세요.';}};
 $('load').onclick=()=>{try{const raw=localStorage.getItem('cct-saved-session-v2');if(raw){const saved=JSON.parse(raw);showLesson(saved.lesson,validate(saved.shot));}else{const shot=localStorage.getItem('cct-shot-v1');if(!shot)throw Error('저장된 촬영이 없습니다.');showLesson(lesson,validate(JSON.parse(shot)));}$('viewing').textContent='저장된 문제와 촬영 설계를 불러왔습니다.';}catch(e){$('viewing').textContent=e.message;}};
 window.__learning={current:()=>structuredClone(lesson),evaluate:()=>evaluate(active()),history:()=>structuredClone(history)};
 showLesson(lesson);historyUI();
}
